  screen: vec2<f32>,    // dimensioni canvas in px device
  layerAlpha: f32,
  strokeOpacity: f32,
  mode: u32,            // 0 chunk, 1 paint combinato, 2 gomma, 3 solo tratto
  blendFn: u32,         // fsBlend: 0 multiply, 1 overlay, 2 softlight, 3 darken, 4 lighten, 5 difference
